={{ (() => {
  const raw = String($("Inbound Lead Webhook").item.json.body?.phone ?? $("Inbound Lead Webhook").item.json.phone ?? "").trim();
  if (!raw || ["idk", "n/a", "none", "0000000000", "1234567890"].includes(raw.toLowerCase())) return "";
  const primary = raw.replace(/\.0+$/, "").split(/\s*(?:ext|x|\/|or|,)/i)[0] || "";
  const digits = primary.replace(/\D/g, "");
  if (digits === "0000000000" || digits === "1234567890") return "";
  if (digits.length === 11 && digits.startsWith("1")) return "+" + digits;
  if (digits.length === 10) return "+1" + digits;
  return "";
})() }}

={{ (() => {
  const raw = String($("Inbound Lead Webhook").item.json.body?.email ?? $("Inbound Lead Webhook").item.json.email ?? "").trim().toLowerCase();
  if (!raw || !raw.includes("@") || raw.length < 5) return "";
  const primary = raw.split(/[;,]/)[0].trim().replace(/^\.+|\.+$/g, "");
  const parts = primary.split("@");
  if (parts.length !== 2 || !parts[0] || !parts[1]) return "";
  const bad = ["idk", "n/a", "na", "none", "null", "nan", "test", "dummy", "noemail", "fake"];
  if (bad.includes(parts[0])) return "";
  const domainMap = { "gamil.com": "gmail.com", "gmial.com": "gmail.com", "gmal.com": "gmail.com", "yaho.com": "yahoo.com", "yahoocom": "yahoo.com", "hotmai.com": "hotmail.com", "outlok.com": "outlook.com" };
  const domain = domainMap[parts[1]] || parts[1];
  return parts[0] + "@" + domain;
})() }}

={{ (() => {
  const raw = String($("Inbound Lead Webhook").item.json.body?.email ?? $("Inbound Lead Webhook").item.json.email ?? "").trim().toLowerCase();
