={{ (() => {
  const f = String($("Inbound Lead Webhook").item.json.body?.first_name ?? $("Inbound Lead Webhook").item.json.first_name ?? "").trim().toLowerCase();
  const l = String($("Inbound Lead Webhook").item.json.body?.last_name ?? $("Inbound Lead Webhook").item.json.last_name ?? "").trim().toLowerCase();
  const bad = ["idk", "n/a", "na", "none", "null", "nan", "unknown", "dummy", "test", "asdf"];
  if ((!f && !l) || bad.includes(f) || bad.includes(l)) return true;
  const status = String($("Inbound Lead Webhook").item.json.body?.lead_status ?? $("Inbound Lead Webhook").item.json.lead_status ?? "").toLowerCase();
  if (["canceled", "voided", "disputed", "dead"].some(s => status.includes(s))) return true;
  const pRaw = String($("Inbound Lead Webhook").item.json.body?.phone ?? $("Inbound Lead Webhook").item.json.phone ?? "").replace(/\.0+$/, "").replace(/\D/g, "");
  const validPhone = (pRaw.length === 10 || (pRaw.length === 11 && pRaw.startsWith("1"))) && pRaw !== "0000000000";
  const eRaw = String($("Inbound Lead Webhook").item.json.body?.email ?? $("Inbound Lead Webhook").item.json.email ?? "").trim().toLowerCase();
  const validEmail = eRaw.includes("@") && eRaw.length >= 5 && !bad.includes(eRaw.split("@")[0]);
  return !validPhone && !validEmail;
})() }}

={{ (() => {
  const opt = String($("Inbound Lead Webhook").item.json.body?.compliance_opt_out ?? $("Inbound Lead Webhook").item.json.compliance_opt_out ?? "").trim().toLowerCase();
  const notes = String($("Inbound Lead Webhook").item.json.body?.notes ?? $("Inbound Lead Webhook").item.json.notes ?? "").toLowerCase();
  if (["true", "1", "yes", "y", "dnc"].includes(opt) || ["dnc", "do not call", "unsubscribe"].some(k => notes.includes(k))) return "[DNC] Explicit TCPA opt-out or DNC compliance keyword detected";
  const eRaw = String($("Inbound Lead Webhook").item.json.body?.email ?? $("Inbound Lead Webhook").item.json.email ?? "").trim().toLowerCase();
  const domain = eRaw.split("@")[1]?.split(/[;,]/)[0]?.trim() || "";
  if (["mailinator.com", "10minutemail.com", "tempmail.com", "yopmail.com"].includes(domain)) return "[DISPOSABLE] Burner email domain blocked";
  return "[TRASH] Missing viable contact channels or test/gibberish name indicator";
})() }}

